using System;using System.IO;using System.Linq;using System.Text;using Frociart;
public static class ExpressionBoundaryTests {
 public static int Main(string[] args){try{string root=args[0];Directory.CreateDirectory(Path.Combine(root,"fixtures"));Directory.CreateDirectory(Path.Combine(root,"expected"));Directory.CreateDirectory(Path.Combine(root,"java-code"));int checks=0;string grow="x = \""+new String('x',4096)+"\"\nx = x & x\nx = x & x\nx = x & x\n";string function="FUNZIONE segna(valori: RIF INTERO[], cifra: INTERO) -> INTERO r\nvalori[0] = valori[0] * 10 + cifra\nr = cifra\nFINE FUNZIONE\nDICHIARA v: INTERO[1]\n";
  string[] names={"concat-boundary","concat-overflow","concat-reference-order","concat-left-snapshot"};string[] code={grow+"STAMPA x & \"\"",grow+"STAMPA x & 1",function+"STAMPA segna(v, 1) & segna(v, 2)\nSTAMPA v[0]",function+"STAMPA v & segna(v, 1)\nSTAMPA v[0]"};string[][] expected={new[]{new String('x',32768)},new string[0],new[]{"12","12"},new[]{"[0]1","1"}};
  for(int i=0;i<names.Length;i++){var d=FlowPseudocode.Decode(code[i]);var r=new Interpreter(d);for(int n=0;n<100&&r.State!=RuntimeState.Completed&&r.State!=RuntimeState.Error;n++)r.Step();if(r.State!=(i==1?RuntimeState.Error:RuntimeState.Completed)||!r.Output.SequenceEqual(expected[i]))throw new Exception(names[i]+" "+r.State+" "+r.Error+" "+String.Join("|",r.Output));checks++;File.WriteAllBytes(Path.Combine(root,"fixtures",names[i]+".frociart"),DiagramIO.EncodeDocument(d));}Console.WriteLine("EXPRESSION_BOUNDARY PASS checks="+checks);return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}
